al-align:top}.map{margin-top:7px;border:1px solid #eaecf0;border-radius:14px;overflow:hidden}.map iframe{display:block;width:100%;height:180px;border:0}.tag{display:inline-block;padding:5px 8px;border-radius:999px;background:#eef2ff;font-size:12px;font-weight:900}.toast{position:fixed;right:18px;bottom:18px;background:#101828;color:#fff;padding:12px 15px;border-radius:12px;display:none;z-index:50}@media(max-width:1000px){.stats{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}}@media(max-width:700px){.side{width:68px}.brand{font-size:0;text-align:center}.brand:after{content:'🌯';font-size:24px}.nav button{font-size:0;text-align:center}.nav button:first-letter{font-size:19px}.main{margin-left:68px;width:calc(100% - 68px);padding:12px}.stats{grid-template-columns:1fr 1fr}.top h1{font-size:20px}}
