</main></div><div id="toast" class="toast"></div><script>const $=s=>document.querySelector(s),api=(a,o={})=>fetch('admin_dashboard_api.php?action='+a,o).then(r=>r.json()),esc=x=>String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m])),toast=t=>{let e=$('#toast');e.textContent=t;e.style.display='block';setTimeout(()=>e.style.display='none',1800)},map=(x)=>{let lat=Number(x.lat),lng=Number(x.lng);if(!lat||!lng)return '<span style="color:#98a2b3">📍 Lokatsiya yo‘q</span>';let q=encodeURIComponent(lat+','+lng);return '<div class="map"><iframe loading="lazy" src="https://maps.google.com/maps?q='+q+'&z=16&output=embed"></iframe></div><a class="tag" target="_blank" rel="noopener" href="https://www.google.com/maps/dir/?api=1&destination='+q+'">🧭 Yo‘l</a>'};
async function dash(){let d=await api('dashboard');if(!d.ok)return;let x=d.data;orders.textContent=x.orders;sales.textContent=Number(x.sales).toLocaleString('uz-UZ')+' so‘m';completed.textContent=Number(x.completed_sales).toLocaleString('uz-UZ')+' so‘m';new.textContent=x.new;couriers.textContent=x.online_couriers;cycle.textContent=x.cycle_label}async function loadLive(){let d=await api('history&from='+encodeURIComponent(new Date(Date.now()-86400000).toISOString().slice(0,19).replace('T',' ')));if(!d.ok)return;let f=$('#statusFilter').value;let rows=d.data.filter(x=>!f||x.status===f);rows=rows.filter(x=>!['completed','cancelled'].includes(x.status));$('#liveTable').innerHTML='<table class="table"><thead><tr><th>#</th><th>Mijoz</th><th>Manzil</th><th>Summa</th><th>Kuryer</th><th>Status</th></tr></thead><tbody>'+rows.map(x=>'<tr><td>#'+x.id+'<br><small>'+new Date(x.created_at).toLocaleString('uz-UZ')+'</small></td><td><b>'+esc(x.customer_name)+'</b><br>'+esc(x.phone)+'<br><small>'+esc(x.note||'')+'</small></td><td>'+esc(x.address||'')+map(x)+'</td><td><b>'+Number(x.amount).toLocaleString('uz-UZ')+' so‘m</b><br>'+((x.payment_method||'cash')==='card'?'💳 Karta':'💵 Naqd')+'</td><td>'+esc(x.courier_name||'—')+'</td><td><span class="tag">'+esc(x.status)+'</span></td></tr>').join('')||'<tr><td colspan="6">Jonli buyurtma yo‘q</td></tr></tbody></table>'}async function loadHistory(mode){let u='admin_dashboard_api.php?action=history';if(mode==='today'){let d=await api('dashboard');u+='&from='+encodeURIComponent(d.data.cycle_start)+'&to='+encodeURIComponent(d.data.cycle_end)}let s=$('#histStatus').value;if(s)u+='&status='+encodeURIComponent(s);let d=await fetch(u).then(r=>r.json());if(!d.ok)return;$('#historyTable').innerHTML='<table class="table"><thead><tr><th>#</th><th>Vaqt</th><th>Mijoz</th><th>Summa</th><th>To‘lov</th><th>Kuryer</th><th>Status</th></tr></thead><tbody>'+d.data.map(x=>'<tr><td>#'+x.id+'</td><td>'+new Date(x.created_at).toLocaleString('uz-UZ')+'</td><td>'+esc(x.customer_name)+'<br>'+esc(x.phone)+'</td><td><b>'+Number(x.amount).toLocaleString('uz-UZ')+' so‘m</b></td><td>'+((x.payment_method||'cash')==='card'?'💳 Karta':'💵 Naqd')+'</td><td>'+esc(x.courier_name||'—')+'</td><td>'+esc(x.status)+'</td></tr>').join('')+'</tbody></table>'}function todayHistory(){loadHistory('today')}function allHistory(){loadHistory('all')}
document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav button').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.section').forEach(s=>s.classList.remove('active'));$('#'+b.dataset.s).classList.add('active');if(b.dataset.s==='history')todayHistory();if(b.dataset.s==='live')loadLive()});logout.onclick=async()=>{await fetch('admin_pro_api.php?action=logout');location.reload()};dash();setInterval(()=>{dash();if($('#live').classList.contains('active'))loadLive();},10000);</script></body></html><?php endif; ?>